import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduction_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void min_reduction_kernel(const float* input, float* output, int reduction_size, int output_size,
                                     int dim0, int dim1, int dim2, int s0, int s1, int s2,
                                     int reduce_dim, int reduce_stride) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= output_size) return;

    int base_offset = 0;
    if (reduce_dim == 1) {
        int b = idx / dim2;
        int d2 = idx % dim2;
        base_offset = b * s0 + d2 * s2;
    } else if (reduce_dim == 2) {
        int b = idx / dim1;
        int d1 = idx % dim1;
        base_offset = b * s0 + d1 * s1;
    } else { // dim0
        int d1 = idx / dim2;
        int d2 = idx % dim2;
        base_offset = d1 * s1 + d2 * s2;
    }

    float min_val = input[base_offset];
    for(int i=1; i<reduction_size; ++i) {
        int offset = base_offset + i * reduce_stride;
        float val = input[offset];
        if(val < min_val) min_val = val;
    }
    output[idx] = min_val;
}

torch::Tensor min_reduction_cuda(torch::Tensor input, int dim) {
    input = input.contiguous();
    auto sizes = input.sizes().vec();
    TORCH_CHECK(sizes.size() == 3, "Input must be 3D");
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be 0, 1, or 2");

    int64_t reduction_size = input.size(dim);
    sizes.erase(sizes.begin() + dim);
    auto output = torch::empty(sizes, input.options());

    int output_numel = output.numel();
    if(output_numel == 0) return output;

    int dim0 = input.size(0);
    int dim1 = input.size(1);
    int dim2 = input.size(2);

    auto strides = input.strides().vec();
    int reduce_stride = strides[dim];

    const int block_size = 256;
    int num_blocks = (output_numel + block_size - 1) / block_size;

    min_reduction_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        reduction_size,
        output_numel,
        dim0, dim1, dim2,
        strides[0], strides[1], strides[2],
        dim,
        reduce_stride
    );

    return output;
}
"""

min_reduction_cpp_source = "torch::Tensor min_reduction_cuda(torch::Tensor input, int dim);"

min_reduction = load_inline(
    name='min_reduction',
    cpp_sources=min_reduction_cpp_source,
    cuda_sources=min_reduction_source,
    functions=['min_reduction_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduction = min_reduction

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.min_reduction.min_reduction_cuda(x, self.dim)
